-- 此文件工具自动生成，不要修改
---@class cfg_equip_entryLib_column
---引援item表id
---ID命名规则
---共八位
---第一位：装备类型 
---二三位：装备子类型
---第四位：职业ID（弓箭手的智力装备ID=4）
---五六位：装备的品阶
---第七位：装备的品质（白装，卓越，套装...）
---第八位：装备的编号
---@field id number @id column=1 A
---装备名称
---@field name string @ column=2 B
---默认不填是单手
---填1是双手武器
---@field twoHanded number @单双手武器 column=3 C
---副手武器的使用要求的职业，引援career职业表
---格式：所属职业#职业等级 多职业间用|分隔
---0或空为无职业限制
---@field assistantJob IntListList @副手武器职业限制 column=4 D
---装备的初始评分
---0-99：白装
---100-199：卓越
---200-299：首饰
---300-399：套装
---@field initialRating number @初始评分 column=5 E
---用来判断装备替换的评分
---
---替换组#替换评分
---
---
---groupid：
---1：物理
---2：魔法
---3：防御
---@field replaceRating IntList @装备评分 column=6 F
---卓越属性是否允许同词条出现
---0或空为不允许
---1为允许
---@field isSameAtt number @同词条限制 column=7 G
---词条引用equip_att表词条库组 1代表从1词条组随一个 1#2代表从1和2词条组中随一个 3|3代表从1词条组随两个
---@field att1 IntListList @词条 column=8 H
---数量#权重|数量#权重，上限不能超过词条配置的数量
---@field attCountweight IntListList @词条数量权重 column=9 I
---属性id#数值|属性id#数值
---@field attribute IntListList @基础属性 column=10 J
---属性id#数值|属性id#数值
---@field useAttLimit IntListList @穿戴属性要求 column=11 K
---所需属性点等级
---@field useAttLv number @所需属性点等级 column=12 L
---掉落时概率携带的技能id#等级#携带概率（万分比）
---@field skillGemProbability IntList @默认携带技能概率 column=13 M
---装备再生组别 物理武器 魔法武器 防具 不配没有
---@field zaisheng_group string @装备再生组别 column=14 N
---当装备配置套装基础属性
---概率#属性ID#属性值1#属性值2#属性值3.....
---|属性2概率........
---@field suitAtt IntListList @套装属性基础加成属性 column=15 O
---配置ID相同的装备，会归类到一个组中。
---用于触发强化大师的等级。不填写则没有
---@field enhancementMaster number @强化大师分组 column=16 P

